macro_rules! deps {
    () => {
        Ref!();
    };
}

macro_rules! string {
    () => {
        deps!();
        # [doc = " Accepts a replacement string and interpolates capture references with their"] # [doc = " corresponding values."] # [doc = ""] # [doc = " `append` should be a function that appends the string value of a capture"] # [doc = " group at a particular index to the string given. If the capture group"] # [doc = " index is invalid, then nothing should be appended."] # [doc = ""] # [doc = " `name_to_index` should be a function that maps a capture group name to a"] # [doc = " capture group index. If the given name doesn't exist, then `None` should"] # [doc = " be returned."] # [doc = ""] # [doc = " Finally, `dst` is where the final interpolated contents should be written."] # [doc = " If `replacement` contains no capture group references, then `dst` will be"] # [doc = " equivalent to `replacement`."] # [doc = ""] # [doc = " See the [module documentation](self) for details about the format"] # [doc = " supported."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::util::interpolate;"] # [doc = ""] # [doc = " let mut dst = String::new();"] # [doc = " interpolate::string("] # [doc = "     \"foo $bar baz\","] # [doc = "     |index, dst| {"] # [doc = "         if index == 0 {"] # [doc = "             dst.push_str(\"BAR\");"] # [doc = "         }"] # [doc = "     },"] # [doc = "     |name| {"] # [doc = "         if name == \"bar\" {"] # [doc = "             Some(0)"] # [doc = "         } else {"] # [doc = "             None"] # [doc = "         }"] # [doc = "     },"] # [doc = "     &mut dst,"] # [doc = " );"] # [doc = " assert_eq!(\"foo BAR baz\", dst);"] # [doc = " ```"] pub fn string (mut replacement : & str , mut append : impl FnMut (usize , & mut String) , mut name_to_index : impl FnMut (& str) -> Option < usize > , dst : & mut String ,) { while ! replacement . is_empty () { match memchr (b'$' , replacement . as_bytes ()) { None => break , Some (i) => { dst . push_str (& replacement [.. i]) ; replacement = & replacement [i ..] ; } } if replacement . as_bytes () . get (1) . map_or (false , | & b | b == b'$') { dst . push_str ("$") ; replacement = & replacement [2 ..] ; continue ; } debug_assert ! (! replacement . is_empty ()) ; let cap_ref = match find_cap_ref (replacement . as_bytes ()) { Some (cap_ref) => cap_ref , None => { dst . push_str ("$") ; replacement = & replacement [1 ..] ; continue ; } } ; replacement = & replacement [cap_ref . end ..] ; match cap_ref . cap { Ref :: Number (i) => append (i , dst) , Ref :: Named (name) => { if let Some (i) = name_to_index (name) { append (i , dst) ; } } } } dst . push_str (replacement) ; }
    };
}

string!();